/* --------------------------------------------------------------------------
   LeNet-5 weights, quantised for the browser
   GENERATED by scripts/generate-lenet-weights.mjs — do not edit by hand.

   Run:  npm run generate-lenet-weights

   Source:      data/cnn-model.json (float32, lenet5-28)
   Parameters:  44 426
   Test acc.:   98.20% (float32, full MNIST test split)

   The five weight tensors are int8 with a per-tensor symmetric scale
   (value = int8 * scale); the five bias vectors stay float32 because they
   are only 236 numbers and a quantised bias shifts an entire channel.

   Quantisation cost, measured on the ten committed samples:
     predictions unchanged: 10/10
     max |Δp| across all classes: 6.84e-3

   Imported only by js/mnist-lab.js (projects/mnist-lenet.html), behind a
   dynamic import. No other page downloads any of this.
-------------------------------------------------------------------------- */

export const LENET = {
  arch: "lenet5-28",
  params: 44426,
  testAccuracy: 0.982,
  epochs: 18,
  quant: 'int8-per-tensor',
  /* int8 tensors: value = byte * scale */
  scales: {
    w1: 0.014661555215129702,
    w2: 0.02854766808156892,
    w3: 0.016434954845999168,
    w4: 0.011462567359443725,
    w5: 0.01994902881111686,
  },
  weights: {
    w1: '3969vvQO9sq9/hQD/tYFGen45QMw9iPrGiXyEenYBwT+qQENDbPPCg34oAAG/tX8GRj4Iev+IQIJEPABAQMCJSDcIzL/wMOOhqkB8uTLyNK+io6QsqONjY2yo42NhdO9ra7T+Pr88fYk//L8ESIB1Q4IIgXW/RQx/PXy3B/2EuXJ+eUR5fkV3yIVMvy1/hDtgcSfmqcr',
    w2: '',
    w3: '',
    w4: '',
    w5: '',
  },
  /* float32 little-endian */
  biases: {
    b1: 'MOQfwJH4w7+r5re/Dp43wbRVhsAqV6nA',
    b2: 'wHgyv6rh+z/cSQG/vki3viEZ0r6I+ZS+Axb6vvrfD76h+42+v7buvqXIUz+ZVoY/oefvvnEHWD6H3Bm+vcCQvg==',
    b3: '',
    b4: '',
    b5: 'OekDvReqk77UzNy9jq5NPQr5CD1OdUs+ffWlvn8plbzGW5Q9pvzUPg==',
  },
};

/* base64 -> Int8Array (weights) */
function decodeInt8(b64) {
  const bin = atob(b64);
  const out = new Int8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = (bin.charCodeAt(i) << 24) >> 24;
  return out;
}

/* base64 -> Float32Array (biases), little-endian */
function decodeFloat32(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Float32Array(bytes.buffer);
}

/* Dequantise into the { w1, b1, ... } bag js/lenet.js forward() expects.
   Called once per page load; ~44 k multiplications, well under a frame. */
export function loadModel() {
  const m = {};
  for (const key of Object.keys(LENET.weights)) {
    const q = decodeInt8(LENET.weights[key]);
    const scale = LENET.scales[key];
    const out = new Float32Array(q.length);
    for (let i = 0; i < q.length; i++) out[i] = q[i] * scale;
    m[key] = out;
  }
  for (const key of Object.keys(LENET.biases)) m[key] = decodeFloat32(LENET.biases[key]);
  return m;
}
